  tabVerify: ['تحقق من تقرير', 'Verify a report'],
  sigAlg: ['خوارزمية التوقيع', 'Signature algorithm'],
  keyFingerprint: ['بصمة مفتاح التوقيع (SHA-256)', 'Signing key fingerprint (SHA-256)'],
